const dayNames=['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه'];
const shortDays=['ش','ی','د','س','چ','پ','ج'];
const ORDER=['A','B','C','D'];
const BASE={version:2,createdAt:null,schedule:{6:'A',0:'B',2:'C',4:'D'},profile:{weight:86.5,goal:81,calories:2450,protein:170,carbs:275,fat:75,water:8,timezone:'Asia/Tehran'},sessions:{},nutrition:{},weights:[]};
let state,tab='home',selectedPlan='A',openEx=null,calendarOffset=0,modalOpen=false,sceneLoaded=false,toastTimer=null;
function safeLoad(){for(const key of ['mobingym_v2','mobingym_backup_v2'])try{const raw=localStorage.getItem(key);if(raw){const s=JSON.parse(raw);if(s&&s.version===2&&s.sessions){return {...structuredClone(BASE),...s,profile:{...BASE.profile,...s.profile},schedule:{...BASE.schedule,...s.schedule},nutrition:s.nutrition||{},weights:s.weights||[]}}}}catch(e){}return structuredClone(BASE)}
state=safeLoad();
function isoByZone(date=new Date()){const f=new Intl.DateTimeFormat('en-US',{timeZone:state.profile.timezone||'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);const ob=Object.fromEntries(f.filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));return `${ob.year}-${ob.month}-${ob.day}`}
function isoDay(iso,add){const d=new Date(`${iso}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+add);return d.toISOString().slice(0,10)}
function dayOf(iso){return new Date(`${iso}T12:00:00Z`).getUTCDay()}
function jalali(iso,opts={year:'numeric',month:'long',day:'numeric'}){return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{...opts,timeZone:'UTC'}).format(new Date(`${iso}T12:00:00Z`))}
function jpart(iso){const parts=new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'numeric',day:'numeric',timeZone:'UTC'}).formatToParts(new Date(`${iso}T12:00:00Z`));return Object.fromEntries(parts.filter(x=>x.type!=='literal').map(x=>[x.type,Number(x.value)]))}
function weekStart(iso){return isoDay(iso,-((dayOf(iso)+1)%7))}
function weekLogs(iso){const start=weekStart(iso),end=isoDay(start,6);return Object.entries(state.sessions).filter(([d,s])=>d>=start&&d<=end&&s.finishedAt)}
const today=()=>isoByZone();
function save(){try{const v=JSON.stringify(state);localStorage.setItem('mobingym_v2',v);localStorage.setItem('mobingym_backup_v2',v)}catch(e){toast('حافظه مرورگر پر شده؛ لطفاً خروجی پشتیبان بگیر.')}}
if(!state.createdAt){state.createdAt=today();save()}
function lastCompleted(){return Object.entries(state.sessions).filter(([,s])=>s.finishedAt).sort((a,b)=>b[0].localeCompare(a[0]))[0]?.[1]||null}
function recommend(){const d=today(),current=state.sessions[d];if(current)return current.plan;const done=weekLogs(d).map(([,s])=>s.plan);const previous=lastCompleted();if(previous){const next=ORDER[(ORDER.indexOf(previous.plan)+1)%4];if(!done.includes(next))return next;}const assigned=state.schedule[dayOf(d)];if(assigned&&!done.includes(assigned))return assigned;return ORDER.find(x=>!done.includes(x))||ORDER[0]}
function currentSession(){return state.sessions[today()]}
function progress(s){if(!s)return {done:0,total:0,percent:0};const p=plans[s.plan];const total=p.ex.reduce((a,e)=>a+e[2],0);const done=Object.values(s.sets||{}).filter(x=>x.done).length;return {total,done,percent:Math.round(done/total*100)}}
function newSession(plan){return {date:today(),plan,startedAt:Date.now(),finishedAt:null,sets:{},note:''}}
function notify(){save();render()}
function goto(next){if(next===tab)return;const swap=()=>{tab=next;openEx=null;window.scrollTo({top:0,behavior:'instant'});render()};if(document.startViewTransition&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){document.startViewTransition(swap)}else{const root=document.querySelector('.page');if(root)root.classList.add('page-exit');setTimeout(swap,135)}}
function toast(msg){const root=document.getElementById('toastRoot');root.innerHTML=`<div class="toast">${escapeHTML(msg)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>root.innerHTML='',3000)}
function weekDates(){const start=weekStart(today());return Array.from({length:7},(_,i)=>isoDay(start,i))}
function completedCount(){return weekLogs(today()).length}
function streak(){const ends=new Set(Object.entries(state.sessions).filter(([,s])=>s.finishedAt).map(([d])=>d));let w=weekStart(today()),n=0;for(let i=0;i<52;i++){let count=0;for(let j=0;j<7;j++)if(ends.has(isoDay(w,j)))count++;if(count===0)break;n++;w=isoDay(w,-7)}return n}
function topbarTitle(){return {home:'داشبورد',workout:'برنامه تمرین',nutrition:'تغذیه هوشمند',history:'سوابق و پیشرفت',music:'موزیک پلیر',settings:'تنظیمات'}[tab]}
function layout(content){const nav=[['home','home','داشبورد'],['workout','dumbbell','تمرین'],['nutrition','utensils','تغذیه'],['history','calendar','سوابق'],['music','play','موزیک'],['settings','settings','تنظیمات']];return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark"><div class="db3d"><i></i><b></b><em></em></div></div><div><div class="brand-name">Mobin<span>GYM</span></div><div class="brand-sub">YOUR STRENGTH UNIVERSE</div></div></div><div><div class="side-label">YOUR WORKSPACE</div><div class="side-links">${nav.map(([id,ico,title])=>`<button class="nav-link ${tab===id?'active':''}" data-tab="${id}">${ic(ico)}${title}</button>`).join('')}</div></div><div class="side-foot"><div class="side-status"><span class="live-dot"></span> حالت ذخیره خودکار فعال</div><strong>یک قدم قوی‌تر، هر روز.</strong><p>پیشرفتت بر اساس تاریخ ذخیره می‌شه.</p><button class="btn btn-sm outline btn-block" data-tab="settings">${ic('shield','tiny')} پشتیبان‌گیری</button></div></aside><main class="main"><div class="topbar"><div class="breadcrumb">MobinGYM / <b>${topbarTitle()}</b></div><div class="top-right"><span class="pill hide-mobile">${ic('clock','tiny')} ${escapeHTML(jalali(today()))}</span><span class="pill">${ic('calendar','tiny')} هفته ${num(Math.max(1,Math.floor((new Date(`${today()}T12:00:00Z`)-new Date(`${state.createdAt}T12:00:00Z`))/604800000)+1))}</span><div class="avatar mini-dumbbell"><div class="db3d"><i></i><b></b><em></em></div></div></div></div><section class="page" id="page">${content}</section></main></div><nav class="mobile-nav">${nav.map(([id,ico,title])=>`<button class="mob-nav-btn ${tab===id?'active':''}" data-tab="${id}">${ic(ico)}<span>${title}</span></button>`).join('')}</nav>`}
function pageHeader(kicker,title,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1 class="page-title">${title}</h1><div class="sub">${sub}</div></div>${extra}</div>`}
function weekStrip(){return `<div class="weeks">${weekDates().map((d,i)=>{const log=state.sessions[d],done=!!log?.finishedAt;return `<div class="week-day ${d===today()?'today':''} ${done?'done':''}"><span>${shortDays[i]}</span><strong>${done?ic('check','tiny'):fi(jpart(d).day)}</strong></div>`}).join('')}</div>`}
function home(){const rec=recommend(),s=currentSession(),p=plans[rec],wp=s?progress(s):null,done=completedCount(),count=Object.keys(state.sessions).length;return `<div class="hero"><div class="hero-copy"><span class="hero-tag"><span class="live-dot"></span> MOBINGYM · PERSONAL FITNESS</span><h1 class="hero-title-animated">برنامه شخصی باشگاه<br/><span class="gradient-txt">MobinGYM</span></h1><div class="hero-actions"><button class="btn primary" data-start="1">${ic('play','sm')} بزن بریم! ${s&&!s.finishedAt?'ادامه تمرین':'تمرین هوشمند امروز'}</button><button class="btn outline" data-tab="history">${ic('trend','sm')} مشاهده پیشرفت</button></div></div><div class="hero-scene"><div class="scene-light"></div><div class="scene-fallback" id="sceneFallback">${fallbackGym()}</div><canvas id="gymCanvas" class="gym-canvas" aria-label="باشگاه سه‌بعدی تعاملی"></canvas><div class="scene-hint"><span>☝️</span> روی ورزشکارها بزن، تعادلشون رو از دست می‌دن!</div></div></div><div class="stats-grid"><div class="card stat"><div class="stat-icon">${ic('dumbbell','lg')}</div><div><div class="stat-label">جلسات این هفته</div><div class="stat-value">${num(done)}<small> / ۴</small></div></div></div><div class="card stat"><div class="stat-icon green">${ic('target','lg')}</div><div><div class="stat-label">هدف وزن</div><div class="stat-value">${num(state.profile.goal)} <small>kg</small></div></div></div><div class="card stat"><div class="stat-icon purple">${ic('weight','lg')}</div><div><div class="stat-label">وزن ثبت‌شده</div><div class="stat-value">${num(state.weights.at(-1)?.weight||state.profile.weight)} <small>kg</small></div></div></div><div class="card stat"><div class="stat-icon gold">${ic('trophy','lg')}</div><div><div class="stat-label">جلسات ثبت‌شده</div><div class="stat-value">${num(Object.values(state.sessions).filter(x=>x.finishedAt).length)} <small>جلسه</small></div></div></div></div><div class="grid-2"><div class="card work-today card-glow"><div class="section-head"><h2>جلسه هوشمند امروز</h2><small>${escapeHTML(jalali(today()))}</small></div><div class="today-info"><div class="session-orb">${rec}</div><div><h3>${p.title}</h3><div class="sub">${p.subtitle}</div><div class="chip-row"><span class="chip">${ic('clock','tiny')} حدود ${num(p.mins)} دقیقه</span><span class="chip">${num(p.ex.length)} حرکت</span><span class="chip">${s?.finishedAt?'انجام شده':'آماده تمرین'}</span></div></div></div><div class="between small"><span class="muted">${s?'پیشرفت ست‌های امروز':'جلسه پیشنهادی'}</span><strong>${s?`${num(wp.done)} از ${num(wp.total)} ست`:p.tag}</strong></div><div class="progress-track mt12"><div class="progress-fill" style="width:${wp?.percent||0}%"></div></div><div class="between mt16"><button class="btn primary" data-start="1">${ic('play','sm')} ${s?.finishedAt?'مشاهده جلسه':'شروع تمرین'}</button><button class="link-btn" data-open="choose">${ic('edit','tiny')} تغییر جلسه</button></div></div><div class="card card-in"><div class="section-head"><h2>فعالیت هفتگی</h2><span class="chip">${num(done)} / ۴ جلسه</span></div><p class="daily-caption">امروز ${escapeHTML(dayNames[dayOf(today())])}، ${escapeHTML(jalali(today()))}</p>${weekStrip()}<div style="margin:21px 0 14px" class="between small"><span>پیشرفت هفتگی</span><strong>${num(Math.round(done/4*100))}٪</strong></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(done,4)*25}%"></div></div><div class="between mt20"><span class="sub">هر جلسه در تقویم ثبت می‌شه.</span><button class="link-btn" data-tab="history">تقویم ${ic('arrow','tiny')}</button></div></div></div><div class="card card-in mt20"><div class="section-head"><h2>قانون طلایی MobinGYM</h2><span class="chip">SMART COACH</span></div><div class="sub">روزهای باشگاهت رو عوض کردی؟ مشکلی نیست. جلسه بعدی بر اساس آخرین تمرین ثبت‌شده پیشنهاد می‌شه و همیشه می‌تونی دستی یکی از A، B، C یا D رو انتخاب کنی. کیفیت اجرای حرکات از زدن وزنه سنگین مهم‌تره.</div></div>`}
