const mediaGuide={chest:'پرس سینه',row:'حرکات زیربغل',pull:'کشیدن عمودی',shoulder:'پرس سرشانه',squat:'اسکوات',hinge:'الگوی هیپ‌هینج',curl:'جلو بازو',pushdown:'پشت بازو',lateral:'نشر جانب',face:'فیس‌پول',legcurl:'پشت پا',legext:'جلو پا',calf:'ساق',hip:'هیپ تراست',core:'تمرین میان‌تنه',lunge:'حرکت تک‌پا'};
function quickAdjust(btn){const field=btn.closest('.quick-ops')?.querySelector('[data-set-field]');if(!field)return;const step=Number(btn.dataset.step||1);const min=Number(field.min||0),max=Number(field.max||9999);const value=Math.max(min,Math.min(max,Math.round((Number(field.value||0)+step)*10)/10));field.value=value;field.dispatchEvent(new Event('input',{bubbles:true}));try{navigator.vibrate?.(12)}catch(e){}}
function previousSet(exid,index){const current=state.sessions[today()];const prev=current?.sets?.[`${exid}:${index-1}`];if(prev?.weight!=null||prev?.reps!=null)return prev;const history=Object.entries(state.sessions).filter(([date,ss])=>date!==today()).sort((a,b)=>b[0].localeCompare(a[0]));for(const [,session] of history){const rec=session.sets?.[`${exid}:${index}`]||session.sets?.[`${exid}:0`];if(rec&&(rec.weight!=null||rec.reps!=null))return rec}return null}
function applyPrevious(id){const ss=getOrCreate(currentSession()?.plan||selectedPlan||recommend());const ex=plans[ss.plan].ex.find(e=>e[0]===id);if(!ex)return;for(let i=0;i<ex[2];i++){const from=previousSet(id,i);if(from){const row=ss.sets[`${id}:${i}`]||{};ss.sets[`${id}:${i}`]={...row,weight:row.weight??from.weight,reps:row.reps??from.reps}}}save();render();toast('آخرین رکوردهای حرکت بارگذاری شدند.');}
function suggestedReps(str){const digits=String(str).replace(/[۰-۹]/g,x=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(x)).match(/\d+/);return digits?Number(digits[0]):10}
function markNextSet(id){const ss=getOrCreate(currentSession()?.plan||selectedPlan||recommend());if(ss.finishedAt){toast('جلسه تمام شده؛ برای ویرایش دوباره بازش کن.');return}const ex=plans[ss.plan].ex.find(e=>e[0]===id);if(!ex)return;let i=Array.from({length:ex[2]},(_,n)=>n).find(n=>!ss.sets[`${id}:${n}`]?.done);if(i==null){openEx=id;render();toast('همه ست‌های این حرکت ثبت شدند.');return}
const source=previousSet(id,i),row=ss.sets[`${id}:${i}`]||{};
ss.sets[`${id}:${i}`]={...row,weight:row.weight??source?.weight,reps:row.reps??source?.reps??suggestedReps(ex[3]),done:true,completedAt:Date.now()};save();startRest(ex[4]);openEx=id;render();const node=document.getElementById('ex-'+id);node?.scrollIntoView({block:'nearest',behavior:'smooth'});try{navigator.vibrate?.(30)}catch(e){};if(progress(ss).done===progress(ss).total){confetti(28);toast('همه ست‌های جلسه تکمیل شدند!')}else toast(`ست ${num(i+1)} ثبت شد ✓`)}
function mediaHint(id){return `<div class="visual-guide"><div class="visual-symbol">${pic((Object.values(plans).flatMap(p=>p.ex).find(e=>e[0]===id)||[])[5]||'chest',true)}</div><div><b>انیمیشن راهنمای حرکت</b><small>نمای تصویری آموزشی. حرکت را با دامنه و تکنیک درست اجرا کن.</small></div></div>`}

function pic(type,large=false){let stance='';const pose=(a,b,c,d)=>`<path d="M75 66 L${a} ${b} M75 66 L${c} ${d}" stroke="#7cddff" stroke-width="8" stroke-linecap="round"/>`;const squat=['squat','lunge'].includes(type),armsDown=['hinge','curl','lateral','legcurl','legext','calf','hip'].includes(type),press=['chest','shoulder','pushdown'].includes(type),rowing=['row','pull','face'].includes(type);let arms=armsDown?`<path d="M74 69l-20 29m29-29 20 29"/>`:press?`<path d="M70 70 52 49 52 29M81 70l18-21V29"/>`:rowing?`<path d="M70 69 49 87 36 75M81 69l21 18 13-12"/>`:`<path d="M70 69 52 92m29-23 18 23"/>`;let legs=squat?`<path d="M70 105 48 127 56 157M81 105l23 22-8 30"/>`:`<path d="M70 105 62 159m19-54 13 54"/>`;let extra='';if(['chest','shoulder'].includes(type))extra=`<g class="svg-gear"><path d="M37 28h78" stroke="#a5b6c9" stroke-width="5"/><path d="M39 19v18m76-18v18M34 22v13m86-13v13" stroke="#3dbfff" stroke-width="8"/></g>`;if(['curl','pushdown','lateral'].includes(type))extra=`<g class="svg-gear"><path d="M42 104h68" stroke="#b9d4ee" stroke-width="4"/><rect x="34" y="95" width="8" height="19" rx="2" fill="#2db1fb"/><rect x="110" y="95" width="8" height="19" rx="2" fill="#2db1fb"/></g>`;if(['row','pull','face'].includes(type))extra=`<path d="M20 64h27m56 0h27" stroke="#4095da" stroke-width="2" stroke-dasharray="5 5"/>`;if(type==='core')extra=`<path d="M30 117h91" stroke="#3486ce" stroke-width="4"/><g class="svg-gear"><path d="M82 102 98 88" stroke="#72ecff" stroke-width="4" stroke-linecap="round"/></g>`;if(['legcurl','legext','hip'].includes(type))extra=`<path d="M26 113h95M37 113v36m81-36v36" stroke="#5485af" stroke-width="5"/>`;if(type==='calf')extra=`<path d="M51 161h58" stroke="#2878ab" stroke-width="5"/>`;if(type==='hinge')extra=`<path d="M32 142h87" stroke="#7e9dbe" stroke-width="4"/>`;const arrow=press||rowing?`<path d="M125 45v-20m-6 6 6-6 6 6" stroke="#50d8ff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" class="glowpulse"/>`:squat?`<path d="M128 112v28m-5-5 5 5 5-5" stroke="#50d8ff" stroke-width="2.5" class="glowpulse"/>`:`<path d="M124 104v-24m-5 6 5-6 5 6" stroke="#50d8ff" stroke-width="2.5" class="glowpulse"/>`;return `<svg viewBox="0 0 150 180" role="img" aria-label="نمایش شماتیک متحرک حرکت"><defs><linearGradient id="person-grad" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#8bdfff"/><stop offset="1" stop-color="#338cff"/></linearGradient></defs><ellipse cx="75" cy="169" rx="42" ry="5" fill="#174275"/><g class="svg-person" fill="none" stroke="url(#person-grad)" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"><circle cx="75" cy="33" r="14" fill="#45aef9" stroke="#9fd9ff" stroke-width="2"/><path d="M75 48v57"/>${arms}${legs}</g>${extra}${arrow}</svg>`}
function sessionForView(){const s=currentSession();return s||{plan:selectedPlan,sets:{},date:today()}}
function sessionPage(){const active=currentSession();const plan=active?.plan||selectedPlan||recommend();const p=plans[plan],s=active&&active.plan===plan?active:null;const calc=progress(s||{plan,sets:{}});const isDone=!!s?.finishedAt;return `${pageHeader('TRAINING SESSION','وقت ساختن نسخه قوی‌ترته.','ست به ست پیش برو؛ وزنه و تکرار واقعی هر حرکت رو ثبت کن.',`<button class="btn outline btn-sm" data-open="choose">${ic('edit','sm')} انتخاب جلسه</button>`)}<div class="session-top"><div class="session-tabs">${ORDER.map(id=>`<button class="session-tab ${plan===id?'selected':''}" data-select-plan="${id}"><b>${id}</b><i>${id==='A'||id==='C'?'بالاتنه':'پایین‌تنه'}</i></button>`).join('')}</div><span class="pill">${ic('calendar','tiny')} ${escapeHTML(jalali(today()))}</span></div><div class="card session-summary"><div><span class="eyebrow">${p.tag}</span><h2>${p.title} <span style="color:#73c1ff">· ${p.subtitle}</span></h2><p>${num(p.ex.length)} حرکت · ${num(p.ex.reduce((a,e)=>a+e[2],0))} ست · حدود ${num(p.mins)} دقیقه</p><div class="chip-row mt12"><span class="chip">${ic('clock','tiny')} استراحت کنترل‌شده</span><span class="chip">${ic('target','tiny')} RIR: ۱ تا ۳</span><span class="chip">${s?'در حال ثبت':'آماده شروع'}</span></div></div><div class="ring"><svg viewBox="0 0 96 96"><circle cx="48" cy="48" r="39" class="ring-bg"/><circle cx="48" cy="48" r="39" class="ring-fg" stroke-dasharray="245.04" stroke-dashoffset="${245.04*(1-calc.percent/100)}"/></svg><b>${num(calc.percent)}٪</b></div></div>${isDone?`<div class="done-ribbon">${ic('check')} این جلسه در تاریخ ${escapeHTML(jalali(today()))} ثبت شده. برای اصلاح ست‌ها می‌تونی دوباره بازش کنی. <button class="btn btn-sm outline" data-reopen="1" style="margin-right:10px">ویرایش</button></div>`:''}<div class="exercise-list">${p.ex.map((e,i)=>exerciseCard(e,i,s)).join('')}</div><div class="session-footer"><div><strong>${num(calc.done)} / ${num(calc.total)} ست ثبت شده</strong><small>${isDone?'تمرین امروز ذخیره شده':s?'هر تیک خودکار ذخیره می‌شه':'با اولین ثبت، تمرین امروز ساخته می‌شه'}</small></div><button class="btn ${isDone?'outline':'green'}" data-finish="1">${ic(isDone?'check':'trophy','sm')}${isDone?'جلسه ثبت شده':'پایان و ثبت جلسه'}</button></div>`}
function exerciseCard(e,i,s){const [id,name,sets,reps,rest,type,cue]=e,opened=openEx===id,values=Array.from({length:sets},(_,n)=>s?.sets?.[`${id}:${n}`]||{}),done=values.filter(x=>x.done).length,percent=Math.round(done/sets*100);return `<article class="card exercise ${opened?'open':''}" id="ex-${id}"><div class="exercise-main"><button type="button" class="ex-toggle" data-ex="${id}" aria-expanded="${opened}" aria-label="باز کردن ${escapeHTML(name)}"><div class="exercise-art">${pic(type)}</div><div class="exercise-meta"><h3 class="exercise-title">${num(i+1)}. ${escapeHTML(name)}</h3><div class="exercise-desc">${num(sets)} ست · ${fi(reps)} تکرار · ${num(rest)} ثانیه استراحت</div><div class="exercise-checks">${values.map((v,n)=>`<span class="set-mini ${v.done?'done':''}">${v.done?ic('check','tiny'):num(n+1)}</span>`).join('')}<span class="ex-percent">${num(percent)}٪</span></div></div></button><button class="ex-one-tap ${done===sets?'complete':''}" data-quick-set="${id}" ${s?.finishedAt?'disabled':''} aria-label="ثبت ست بعدی برای ${escapeHTML(name)}">${done===sets?'✓':'+'}<small>${done===sets?'تمام':'ثبت ست'}</small></button><button class="ex-guide" data-preview="${id}" aria-label="نمایش راهنمای حرکت">${ic('play','tiny')}</button></div>${opened?`<div class="exercise-detail"><div class="quick-top"><span>وزنه، تعداد و ست‌های واقعی</span><button class="link-btn" data-fill-last="${id}">${ic('rotate','tiny')} رکورد قبلی</button></div>${Array.from({length:sets},(_,n)=>{const v=values[n];return `<div class="set-entry ${v.done?'set-entry-done':''}"><div class="set-n">${num(n+1)}</div><div class="set-control"><span>وزنه · kg</span><div class="stepper"><button data-step="-2.5" aria-label="کاهش وزن">−</button><input inputmode="decimal" type="number" min="0" max="999" step="0.5" data-set-field="weight" data-exid="${id}" data-set="${n}" value="${escapeHTML(v.weight??previousSet(id,n)?.weight??'')}" placeholder="—"/><button data-step="2.5" aria-label="افزایش وزن">+</button></div></div><div class="set-control"><span>تکرار</span><div class="stepper"><button data-step="-1" aria-label="کاهش تکرار">−</button><input inputmode="numeric" type="number" min="0" max="100" data-set-field="reps" data-exid="${id}" data-set="${n}" value="${escapeHTML(v.reps??previousSet(id,n)?.reps??suggestedReps(reps))}"/><button data-step="1" aria-label="افزایش تکرار">+</button></div></div><button class="set-done ${v.done?'done':''}" data-set-done="${id}:${n}" aria-label="${v.done?'لغو':'ثبت'} ست ${n+1}">${v.done?'✓':'ثبت'}</button></div>`}).join('')}<p class="exercise-footnote">${escapeHTML(cue)}</p><button class="link-btn" data-preview="${id}">مشاهده راهنمای متحرک حرکت ${ic('play','tiny')}</button></div>`:''}</article>`}

function nutritionDay(){const key=today();if(!state.nutrition[key])state.nutrition[key]={water:0,checked:{},options:{}};const d=state.nutrition[key];d.checked??={};d.options??={};d.portions??={};d.extras??=[];d.caffeine??=[];d.water??=0;return d}
function getMeal(m){return m.choices[nutritionDay().options[m.id]||0]}
function dailyMeals(){const d=nutritionDay();return MEALS.map(m=>{const food=getMeal(m),n=d.checked[m.id]?(d.portions[m.id]||1):0;return {...food,id:m.id,n,title:m.title}})}
function consumed(){const d=nutritionDay();const vals=[...dailyMeals(),...d.extras];let k=0,p=0,c=0,f=0;for(const v of vals){const qty=v.n??1;k+=v.k*qty;p+=v.p*qty;c+=v.c*qty;f+=v.f*qty}return {k:Math.round(k),p:Math.round(p),c:Math.round(c),f:Math.round(f)}}
function macroCard(icon,name,value,target,unit,color){const pct=Math.max(0,Math.min(100,(value/Math.max(1,target))*100));return `<div class="card macro-stat"><div class="between"><small>${name}</small><span style="color:${color}">${ic(icon,'sm')}</span></div><strong>${num(Math.round(value))} <span style="font-size:10px;color:#849eb9;font-weight:500">/ ${num(target)} ${unit}</span></strong><div class="mini-track"><span style="width:${pct}%;background:${color}"></span></div></div>`}
function foodCircle(value,max,label,unit,color){const pct=Math.max(0,Math.min(120,(value/Math.max(max,1))*100));return `<div class="food-orbit" style="--percent:${Math.min(pct,100)};--orbcolor:${color}"><div class="food-orbit-inner"><strong>${num(value)}</strong><small>${unit}</small></div><span class="orbit-label">${label}</span></div>`}
function nutritionPage(){const d=nutritionDay(),tot=consumed(),goal=state.profile;const mealCount=MEALS.filter(m=>d.checked[m.id]).length;const pct=tot.k/Math.max(1,goal.calories)*100;const caffeine=d.caffeine.reduce((n,x)=>n+x.mg,0);const waterPct=Math.min(100,d.water/Math.max(1,goal.water)*100);return `${pageHeader('FUEL YOUR PERFORMANCE','تغذیه هوشمند MobinGYM','دریافت واقعی را ثبت کن، اندازه وعده‌ها را تغییر بده و روند روزت را ببین.',`<button class="btn outline btn-sm" data-tab="settings">تنظیم اهداف ${ic('edit','tiny')}</button>`)}<div class="nutrition-hero card"><div class="nutrition-copy"><span class="eyebrow">DAILY FUEL REPORT</span><h2>هر وعده، بخشی از پیشرفتته.</h2><p>کالری مصرف‌شده و پروتئین امروز بر اساس وعده‌هایی که واقعاً خوردی محاسبه می‌شود.</p><div class="nutri-pill">${num(mealCount)} از ${num(MEALS.length)} وعده ثبت‌شده · ${escapeHTML(jalali(today()))}</div></div><div class="food-rings">${foodCircle(tot.k,goal.calories,'کالری','kcal','#50bfff')}${foodCircle(tot.p,goal.protein,'پروتئین','g','#4ce6bd')}</div></div><div class="macro-grid">${macroCard('fire','کالری',tot.k,goal.calories,'kcal','#48aeff')}${macroCard('dumbbell','پروتئین',tot.p,goal.protein,'g','#53e0b3')}${macroCard('trend','کربوهیدرات',tot.c,goal.carbs,'g','#b694fa')}${macroCard('water','چربی',tot.f,goal.fat,'g','#ffca75')}</div><div class="card card-in mt20"><div class="between"><b>نمودار تأمین انرژی روزانه</b><strong class="blue">${num(Math.round(pct))}٪</strong></div><div class="nutri-track"><div class="nutri-fill" style="width:${Math.min(pct,100)}%"></div></div><small class="muted">${num(tot.k)} از ${num(goal.calories)} کیلوکالری · ${pct>100?'بیشتر از هدف':`حدود ${num(Math.max(0,goal.calories-tot.k))} کالری تا هدف باقی مانده`}</small></div><div class="card smart-fuel-card"><span class="eyebrow">SMART FUEL COACH</span><div class="smartfuel-row"><div><b>پیشنهاد هوشمند امروز</b><p>${tot.p<goal.protein?`حدود ${num(goal.protein-tot.p)} گرم پروتئین تا هدف باقی مانده؛ می‌تونی یک منبع پروتئین متناسب با کالری باقی‌مانده انتخاب کنی.`:'پروتئین هدف امروزت تأمین شده. روی تعادل انرژی و کیفیت غذا تمرکز کن.'}</p></div><span>✦</span></div><small>این پیشنهاد از مجموع ثبت‌های امروز محاسبه می‌شود، نه از عکس غذا یا داده پزشکی.</small></div><div class="section-head mt20"><h2>وعده‌های امروز</h2><small>انتخاب مستقل و اندازه قابل تنظیم</small></div><div class="meals">${MEALS.map((m,i)=>{const food=getMeal(m),checked=!!d.checked[m.id],portion=d.portions[m.id]||1;return `<article class="card meal ${checked?'meal-done':''}" style="--meal-delay:${i*65}ms"><div class="meal-head"><div class="meal-icon">${m.emoji}</div><div><h3>${m.title}</h3><div class="meal-time">${fi(m.time)} · ${food.name}</div></div><div class="meal-number">۰${num(i+1)}</div></div><p class="meal-content">${food.items}</p><div class="meal-chips"><span class="macro-chip">${num(Math.round(food.k*portion))} kcal</span><span class="macro-chip">${num(Math.round(food.p*portion))}g پروتئین</span><span class="macro-chip">${num(Math.round(food.c*portion))}g کربوهیدرات</span></div><div class="portion-line"><span>مقدار مصرفی</span><div class="portion-tabs">${[.5,1,1.5,2].map(x=>`<button class="${portion===x?'active':''}" data-portion="${m.id}:${x}">${num(x)}×</button>`).join('')}</div></div><div class="meal-actions"><button class="btn btn-sm ${checked?'green':'primary'}" data-meal="${m.id}">${checked?'✓ ثبت شد':'ثبت مصرف'}</button><button class="link-btn" data-swap-meal="${m.id}">${ic('rotate','tiny')} جایگزین</button></div></article>`}).join('')}</div><div class="card card-in mt20"><div class="section-head"><h2>${ic('plus','sm')} ثبت غذای دلخواه</h2><span class="chip">EXTRA FOOD</span></div><form class="extra-food-form" id="extraFoodForm"><input class="field" name="name" required maxlength="60" placeholder="مثلاً یک لیوان شیر"/><input class="field" type="number" name="k" required min="0" max="3000" placeholder="کالری"/><input class="field" type="number" name="p" min="0" max="300" placeholder="پروتئین (g)"/><button class="btn primary" type="submit">افزودن غذا</button></form>${d.extras.length?`<div class="extra-entries">${d.extras.map((x,i)=>`<div class="between"><span>${escapeHTML(x.name)} · ${num(x.k)} kcal · ${num(x.p)}g پروتئین</span><button class="link-btn" data-remove-food="${i}">حذف</button></div>`).join('')}</div>`:''}</div><div class="grid-2 mt20"><div class="card card-in water-panel"><div class="section-head"><h2>💧 آب روزانه</h2><small>هر لیوان تقریباً ۲۵۰ میلی‌لیتر</small></div><div class="water-meter" style="--water-level:${waterPct}%"><div class="water-wave"></div><div class="water-wave2"></div>${Array.from({length:10},()=>'<span class="bubble-fx"></span>').join('')}<div class="wm-label"><div><strong>${num(d.water)}</strong><br/><small>از ${num(goal.water)} لیوان · ${num(d.water*250)} ml</small></div></div></div><div class="water-ops"><button data-water="-1">− یک لیوان</button><button class="primary" data-water="1">+ یک لیوان</button><button data-water="2">+ دو لیوان</button></div><p class="sub">هدف نوشیدن آب قابل تنظیم است؛ نیاز واقعی به میزان تعریق، گرما و وضعیت سلامتی بستگی دارد.</p></div><div class="card card-in caffeine-panel"><div class="section-head"><h2>☕ کافئین و قهوه</h2><span class="chip">CAFFEINE TRACKER</span></div><div class="coffee-stage"><div class="coffee-cup"><div class="coffee-surface" style="height:${Math.min(100,caffeine/400*100)}%"></div><div class="steam a"></div><div class="steam b"></div><div class="steam c"></div></div><div><strong>${num(caffeine)} <small>mg</small></strong><div class="sub">کافئین ثبت‌شده امروز</div><span class="chip">مجموع تخمینی</span></div></div><div class="coffee-choices">${[['اسپرسو',65],['دبل اسپرسو',130],['قهوه دمی',100],['چای',35]].map(([name,mg])=>`<button data-coffee="${name}:${mg}">${name}<small>+${num(mg)} mg</small></button>`).join('')}</div>${d.caffeine.length?`<div class="extra-entries">${d.caffeine.map((x,i)=>`<div class="between"><span>${escapeHTML(x.name)} · ${num(x.mg)}mg</span><button class="link-btn" data-remove-coffee="${i}">حذف</button></div>`).join('')}</div>`:''}<p class="sub">مقدار واقعی کافئین با نوع دانه، حجم نوشیدنی و روش دم‌آوری تغییر می‌کند. نزدیک زمان خواب با احتیاط مصرف کن.</p></div></div><div class="food-note mt20">این برنامه غذایی یک نقطه شروع عمومی است، نه رژیم پزشکی؛ ارزش غذایی اقلام تقریبی است. هر وعده فقط زمانی حساب می‌شود که «ثبت مصرف» را بزنـی و حجم واقعی را مشخص کنی.</div>`}

function monthGrid(){const base=isoDay(today(),calendarOffset*29),j=jpart(base);let start=isoDay(base,-(j.day-1));let days=[];for(let i=0;i<32;i++){let d=isoDay(start,i),v=jpart(d);if(v.month!==j.month||v.year!==j.year)break;days.push(d)}let off=(dayOf(start)+1)%7;return `<div class="calendar-month"><button class="btn btn-sm outline" data-cal-nav="-1" aria-label="ماه قبل">${ic('arrow','tiny')}</button><strong>${escapeHTML(jalali(start,{month:'long',year:'numeric'}))}</strong><button class="btn btn-sm outline" data-cal-nav="1" aria-label="ماه بعد" style="transform:rotate(180deg)">${ic('arrow','tiny')}</button></div><div class="calendar-grid">${shortDays.map(x=>`<div class="cal-head">${x}</div>`).join('')}${Array.from({length:off},()=>'<div class="cal-cell empty"></div>').join('')}${days.map(d=>{const log=state.sessions[d];return `<div class="cal-cell ${d===today()?'today':''} ${log?(log.finishedAt?'finished':'logged'):''}" title="${escapeHTML(jalali(d))}${log?' | '+plans[log.plan].title:''}">${fi(jpart(d).day)}</div>`}).join('')}</div><div class="chip-row mt16"><span class="chip">🟢 جلسه ثبت‌شده</span><span class="chip">🔵 جلسه نیمه‌تمام</span></div>`}
function weightChart(){const data=state.weights.slice(-16);if(!data.length)return `<div class="empty-state">${ic('trend','lg')}<div>هر بار وزنت را ثبت کنی، نمودار اینجا شکل می‌گیرد.</div></div>`;const values=data.map(x=>Number(x.weight)),lo=Math.min(...values,Number(state.profile.goal))-1.2,hi=Math.max(...values)+1.2;const pts=data.map((e,i)=>[data.length===1?260:34+i*462/(data.length-1),195-(Number(e.weight)-lo)/(hi-lo)*152]);const path=pts.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '),area=path+` L ${pts.at(-1)[0]} 202 L ${pts[0][0]} 202 Z`;const waist=data.filter(x=>x.waist!=null),wlo=Math.min(...waist.map(x=>x.waist))-1,whi=Math.max(...waist.map(x=>x.waist))+1;const wpath=waist.map((x,i)=>{const ind=data.findIndex(z=>z.date===x.date);return (i?'L':'M')+[pts[ind][0],195-(x.waist-wlo)/Math.max(1,whi-wlo)*150].join(' ')}).join(' ');return `<div class="chart-shell"><div class="chart-legend"><span><i style="background:#58cdff"></i>وزن (kg)</span>${waist.length>1?'<span><i style="background:#40e5ac"></i>دور کمر (cm) · مقیاس جدا</span>':''}</div><svg viewBox="0 0 530 225" role="img" aria-label="نمودار تغییر وزن"><defs><linearGradient id="wgrad" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#39b8ff" stop-opacity=".38"/><stop offset="1" stop-color="#39b8ff" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="30" y1="${25+i*53}" x2="506" y2="${25+i*53}" stroke="#43658d" opacity=".35" stroke-dasharray="3 7"/>`).join('')}<path d="${area}" fill="url(#wgrad)" class="chart-area"/><path d="${path}" stroke="#51caff" stroke-width="3.8" fill="none" class="chart-draw" stroke-linecap="round" stroke-linejoin="round" pathLength="100"/>${waist.length>1?`<path d="${wpath}" fill="none" stroke="#39d9a8" stroke-width="2.6" stroke-linecap="round" stroke-dasharray="6 4" class="chart-draw" pathLength="100"/>`:''}${pts.map((xy,i)=>`<g class="chart-dot" style="animation-delay:${i*90}ms"><circle cx="${xy[0]}" cy="${xy[1]}" r="5.6" fill="#a8e9ff" stroke="#0e3351" stroke-width="3"/><text x="${xy[0]}" y="${xy[1]-14}" fill="#cdefff" font-size="11" text-anchor="middle">${fi(values[i])}</text></g>`).join('')}</svg><div class="between sub"><span>${escapeHTML(jalali(data[0].date,{month:'short',day:'numeric'}))}</span><span>${escapeHTML(jalali(data.at(-1).date,{month:'short',day:'numeric'}))}</span></div></div>`}
function historyPage(){const logs=Object.entries(state.sessions).sort((a,b)=>b[0].localeCompare(a[0]));const done=logs.filter(([,s])=>s.finishedAt).length;return `${pageHeader('PERFORMANCE ARCHIVE','هر قدمت، یک رکورد ماندگار.','جلسات، وزن و پیشرفتت با تاریخ دقیق در دستگاهت ذخیره شده‌اند.',`<button class="btn outline btn-sm" data-export="1">${ic('download','sm')} دریافت نسخه پشتیبان</button>`)}<div class="stats-grid"><div class="card stat"><div class="stat-icon">${ic('dumbbell','lg')}</div><div><div class="stat-label">جلسات کامل</div><div class="stat-value">${num(done)}</div></div></div><div class="card stat"><div class="stat-icon green">${ic('check','lg')}</div><div><div class="stat-label">ست‌های انجام‌شده</div><div class="stat-value">${num(logs.reduce((a,[,s])=>a+Object.values(s.sets||{}).filter(x=>x.done).length,0))}</div></div></div><div class="card stat"><div class="stat-icon purple">${ic('calendar','lg')}</div><div><div class="stat-label">این هفته</div><div class="stat-value">${num(completedCount())} <small>جلسه</small></div></div></div><div class="card stat"><div class="stat-icon gold">${ic('weight','lg')}</div><div><div class="stat-label">وزن آخر</div><div class="stat-value">${num(state.weights.at(-1)?.weight||state.profile.weight)} <small>kg</small></div></div></div></div><div class="history-grid"><div class="card calendar">${monthGrid()}</div><div class="card card-in"><div class="section-head"><h2>تاریخچه تمرین‌ها</h2><small>${num(logs.length)} روز دارای اطلاعات</small></div><div class="history-list">${logs.length?logs.map(([date,s])=>{const p=progress(s);return `<div class="history-row"><div class="history-id">${s.plan}</div><div style="flex:1"><strong>${plans[s.plan]?.title||s.plan} · ${escapeHTML(jalali(date))}</strong><small>${num(p.done)} از ${num(p.total)} ست · ${s.finishedAt?'تکمیل شده':'نیمه‌تمام'} ${s.finishedAt&&s.startedAt?' · '+num(Math.round((s.finishedAt-s.startedAt)/60000))+' دقیقه':''}</small></div><span style="color:${s.finishedAt?'#48e5ac':'#72b9ff'}">${ic(s.finishedAt?'check':'clock','sm')}</span></div>`}).join(''):`<div class="empty-state">${ic('calendar','lg')}<div>هنوز جلسه‌ای ثبت نشده. اولین تمرینت رو شروع کن!</div></div>`}</div></div></div><div class="grid-2 mt20"><div class="card chart-card"><div class="section-head"><h2>نمودار تغییر وزن</h2><small>هدف: ${num(state.profile.goal)} کیلوگرم ${state.weights.at(-1)?.waist?' · دور کمر: '+num(state.weights.at(-1).waist)+' سانتی‌متر':''}</small></div>${weightChart()}</div><div class="card card-in"><div class="section-head"><h2>ثبت وزن جدید</h2><span class="chip">BODY PROGRESS</span></div><p class="sub">صبح، ترجیحاً پس از دستشویی و قبل از صبحانه، در شرایط مشابه وزن‌کشی کن. برای قضاوت، میانگین چند روز مهم‌تر از نوسان روزانه است.</p><form id="weightForm" class="record-row"><div class="field-group" style="flex:1"><label class="field-label" for="newWeight">وزن امروز (کیلوگرم)</label><input class="field" type="number" id="newWeight" min="20" max="400" step="0.1" required placeholder="۸۶.۵" value="${escapeHTML(state.weights.find(x=>x.date===today())?.weight||'')}"/></div><div class="field-group" style="flex:1"><label class="field-label" for="newWaist">دور کمر (سانتی‌متر، اختیاری)</label><input class="field" type="number" id="newWaist" min="40" max="220" step="0.5" placeholder="—" value="${escapeHTML(state.weights.find(x=>x.date===today())?.waist||'')}"/></div><button class="btn primary" type="submit">${ic('plus','sm')} ثبت وزن</button></form><div class="food-note">برای جلوگیری از حذف داده‌ها در صورت پاک‌کردن اطلاعات مرورگر یا تعویض گوشی، به‌صورت منظم از تنظیمات خروجی JSON بگیر.</div></div></div>`}

const musicStore={db:null,tracks:[],current:null,playing:false,objectURL:null,ready:false};const playerAudio=new Audio();playerAudio.preload='metadata';playerAudio.addEventListener('ended',()=>musicAction('next'));playerAudio.addEventListener('timeupdate',updateMiniPlayer);playerAudio.addEventListener('play',()=>{musicStore.playing=true;updateMiniPlayer()});playerAudio.addEventListener('pause',()=>{musicStore.playing=false;updateMiniPlayer()});
function openMusicDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('mobingym_music_v1',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('tracks'))request.result.createObjectStore('tracks',{keyPath:'id',autoIncrement:true})};request.onsuccess=()=>{musicStore.db=request.result;resolve(request.result)};request.onerror=()=>reject(request.error)})}
function musicQuery(mode,entry){return new Promise((resolve,reject)=>{const transaction=musicStore.db.transaction('tracks',mode==='all'?'readonly':'readwrite'),store=transaction.objectStore('tracks');const req=mode==='all'?store.getAll():mode==='delete'?store.delete(entry):store.add(entry);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function loadMusic(){try{if(!musicStore.db)await openMusicDB();const rows=await musicQuery('all');musicStore.tracks=rows.sort((a,b)=>a.id-b.id);musicStore.ready=true;if(tab==='music')render();updateMiniPlayer()}catch(e){musicStore.ready=false;console.warn('Music storage:',e)}}
function trackInfo(){return musicStore.tracks.find(t=>t.id===musicStore.current)}
function musicPage(){return `${pageHeader('YOUR ENERGY SOUNDTRACK','موزیک پلیر باشگاه','فایل‌های صوتی را از گوشی اضافه کن؛ لیست پخش در حافظه همین مرورگر می‌ماند.',`<label class="btn primary music-upload">${ic('plus','sm')} افزودن آهنگ<input id="musicFiles" type="file" accept="audio/*" multiple hidden/></label>`)}<div class="music-hero card"><div class="vinyl"><div class="vinyl-label">MG</div></div><div class="music-detail"><div class="eyebrow">MOBINGYM MUSIC STUDIO</div><h2>${escapeHTML(trackInfo()?.name||'آماده تمرین و موسیقی')}</h2><p>فایل‌ها روی سرور آپلود نمی‌شوند؛ فقط در ذخیره‌سازی محلی این دستگاه نگهداری می‌شوند.</p><div class="player-controls"><button data-music-action="prev" aria-label="قبلی">⏮</button><button class="player-primary" data-music-action="toggle" aria-label="پخش یا مکث">${musicStore.playing?'⏸':'▶'}</button><button data-music-action="next" aria-label="بعدی">⏭</button></div><input id="musicSeek" class="music-seek" type="range" min="0" max="100" value="${Number.isFinite(playerAudio.duration)?Math.round(playerAudio.currentTime/playerAudio.duration*100):0}" aria-label="موقعیت آهنگ"/><div class="between sub"><span id="elapsedText">${formatTime(playerAudio.currentTime)}</span><span id="durationText">${formatTime(playerAudio.duration)}</span></div></div></div><div class="card card-in mt20"><div class="section-head"><h2>پلی‌لیست من</h2><small>${num(musicStore.tracks.length)} آهنگ</small></div>${musicStore.tracks.length?`<div class="music-tracks">${musicStore.tracks.map((t,i)=>`<div class="track ${musicStore.current===t.id?'active':''}"><button data-track-id="${t.id}" class="track-play"><span>♫</span></button><div class="track-meta"><b>${escapeHTML(t.name)}</b><small>${num(Math.round(t.size/1048576*10)/10)} MB</small></div><button class="track-remove" data-music-action="remove:${t.id}" aria-label="حذف آهنگ">✕</button></div>`).join('')}</div>`:`<div class="empty-state">هنوز آهنگی اضافه نکردی. از دکمه «افزودن آهنگ» فایل MP3 یا فایل صوتی گوشی رو انتخاب کن.</div>`}</div><div class="food-note mt20">آهنگ‌ها ممکن است فضای ذخیره مرورگر را اشغال کنند و با پاک کردن اطلاعات سایت حذف شوند. مرورگر ممکن است هنگام قفل صفحه پخش را محدود کند. بکاپ JSON شامل فایل‌های موزیک نیست.</div>`}
function formatTime(sec){if(!Number.isFinite(sec)||sec<0)return '۰:۰۰';return `${Math.floor(sec/60)}:${String(Math.floor(sec%60)).padStart(2,'0')}`}
async function uploadMusic(files){if(!musicStore.db)await loadMusic();if(!musicStore.db){toast('حافظه موسیقی در این مرورگر در دسترس نیست.');return}let count=0;for(const f of files){if(!f.type.startsWith('audio/')&&!(f.name.match(/\.(mp3|wav|m4a|ogg|flac)$/i)))continue;if(f.size>70*1024*1024){toast('فایل بیشتر از ۷۰ مگابایت پشتیبانی نمی‌شود.');continue}try{await musicQuery('add',{name:f.name.replace(/\.[^.]+$/,''),type:f.type||'audio/mpeg',size:f.size,blob:f,lastModified:f.lastModified});count++}catch(e){toast('فضای ذخیره پر شده؛ بعضی فایل‌ها اضافه نشدند.');break}}await loadMusic();toast(`${num(count)} فایل به پلی‌لیست اضافه شد.`)}
async function playTrack(id){if(musicStore.current!==id){const t=musicStore.tracks.find(x=>x.id===id);if(!t)return;if(musicStore.objectURL)URL.revokeObjectURL(musicStore.objectURL);musicStore.objectURL=URL.createObjectURL(t.blob);musicStore.current=id;playerAudio.src=musicStore.objectURL}try{await playerAudio.play()}catch(e){toast('برای پخش، دوباره روی دکمه پخش بزن.')}if(tab==='music')render();updateMiniPlayer()}
function musicAction(action){if(action==='toggle'){if(!musicStore.current){if(musicStore.tracks.length)playTrack(musicStore.tracks[0].id);else toast('اول یک فایل موسیقی اضافه کن.')}else if(playerAudio.paused)playerAudio.play().catch(()=>toast('پخش ممکن نشد.'));else playerAudio.pause();if(tab==='music')render();return}if(action==='next'||action==='prev'){if(!musicStore.tracks.length)return;const idx=musicStore.tracks.findIndex(x=>x.id===musicStore.current),shift=action==='next'?1:-1;playTrack(musicStore.tracks[(idx+shift+musicStore.tracks.length)%musicStore.tracks.length].id);return}if(action.startsWith('remove:')){const id=Number(action.split(':')[1]);if(musicStore.current===id){playerAudio.pause();playerAudio.removeAttribute('src');musicStore.current=null;if(musicStore.objectURL)URL.revokeObjectURL(musicStore.objectURL)}musicQuery('delete',id).then(loadMusic);return}}
function updateMiniPlayer(){const el=document.getElementById('musicMini');if(el){el.classList.toggle('visible',!!trackInfo());el.querySelector('.mini-song').textContent=trackInfo()?.name||'';el.querySelector('.mini-play').textContent=musicStore.playing?'⏸':'▶'}const seek=document.getElementById('musicSeek');if(seek&&!seek.matches(':active')&&Number.isFinite(playerAudio.duration)&&playerAudio.duration>0)seek.value=Math.round(playerAudio.currentTime/playerAudio.duration*100);for(const [id,v] of [['elapsedText',formatTime(playerAudio.currentTime)],['durationText',formatTime(playerAudio.duration)]]){const x=document.getElementById(id);if(x)x.textContent=v}}
document.addEventListener('change',e=>{if(e.target.id==='musicFiles'&&e.target.files)uploadMusic(e.target.files)});document.addEventListener('input',e=>{if(e.target.id==='musicSeek'&&Number.isFinite(playerAudio.duration))playerAudio.currentTime=playerAudio.duration*e.target.value/100});

function settingsPage(){return `${pageHeader('YOUR PERSONAL STUDIO','باشگاه رو به سبک خودت بچین.','روزهای تمرین، اهداف تغذیه و اطلاعات شخصی قابل ویرایش هستند.')}<div class="settings-grid"><div class="card settings-card"><h3>${ic('calendar','sm')} چینش روزهای باشگاه</h3><p>هر جلسه رو روی روز دلخواه قرار بده. اگر روزی از قبل اشغال باشه، جای دو جلسه به‌صورت خودکار عوض می‌شه. ترتیب هوشمند تمرین همچنان بر اساس سابقه حفظ می‌شه.</p>${ORDER.map(id=>{const d=Object.keys(state.schedule).find(k=>state.schedule[k]===id);return `<div class="schedule-row"><div class="session-orb">${id}</div><label>${plans[id].title}</label><select class="field" data-schedule="${id}" aria-label="روز جلسه ${id}">${[6,0,1,2,3,4,5].map(x=>`<option value="${x}" ${Number(d)===x?'selected':''}>${dayNames[x]}</option>`).join('')}</select></div>`}).join('')}<div class="tip">${ic('info','sm')} می‌تونی حتی در روز استراحت با انتخاب «بزن بریم» یک جلسه تمرینی رو اجرا کنی.</div></div><div class="card settings-card"><h3>${ic('target','sm')} هدف‌های شخصی</h3><p>اهداف اولیه قابل تنظیم هستند و برنامه غذایی بر اساس عددهای جدید نمایش داده می‌شه.</p><form id="profileForm"><div class="settings-fields">${[['weight','وزن شروع (kg)',20,300,.1],['goal','وزن هدف (kg)',20,300,.1],['calories','هدف کالری روزانه',1000,6000,50],['protein','پروتئین (g)',30,350,5],['carbs','کربوهیدرات (g)',30,600,5],['fat','چربی (g)',15,200,5],['water','آب (لیوان)',1,16,1]].map(([id,label,min,max,step])=>`<div class="field-group"><label class="field-label" for="p_${id}">${label}</label><input class="field" id="p_${id}" type="number" min="${min}" max="${max}" step="${step}" value="${escapeHTML(state.profile[id])}" required/></div>`).join('')}<div class="field-group"><label class="field-label" for="p_timezone">منطقه زمانی</label><select class="field" id="p_timezone"><option value="Asia/Tehran" ${state.profile.timezone==='Asia/Tehran'?'selected':''}>تهران</option><option value="Europe/Berlin" ${state.profile.timezone==='Europe/Berlin'?'selected':''}>برلین</option><option value="UTC" ${state.profile.timezone==='UTC'?'selected':''}>UTC</option></select></div></div><button class="btn primary mt20 btn-block" type="submit">${ic('check','sm')} ذخیره تنظیمات</button></form></div><div class="card settings-card"><h3>${ic('shield','sm')} حفاظت از سوابق</h3><p>همه تیک‌ها، وزن‌ها، تغذیه و روزهای تمرین در فضای ذخیره همین مرورگر ذخیره می‌شن. برای انتقال به گوشی یا مرورگر دیگر نسخه پشتیبان بگیر و در دستگاه جدید وارد کن.</p><div class="warning">⚠️ ذخیره محلی، فضای ابری نیست. پاک‌کردن داده‌های سایت، استفاده از حالت ناشناس یا تعویض دستگاه ممکنه سوابق رو حذف کنه. خروجی JSON رو در فضای امن نگهداری کن.</div><div class="chip-row mt16"><button class="btn primary" data-export="1">${ic('download','sm')} دانلود بکاپ JSON</button><button class="btn outline" data-import="1">${ic('upload','sm')} بازیابی بکاپ</button></div><input id="importFile" type="file" accept="application/json,.json" class="hide"/><div class="food-note">پیشنهاد: هر هفته یک نسخه پشتیبان در Google Drive یا فایل‌های گوشی ذخیره کن. همگام‌سازی ابری خودکار در این نسخه وجود نداره.</div></div><div class="card settings-card notification-settings"><h3>🔔 یادآور باشگاه و نصب اپ</h3><p>برای یادآوری هنگام باز بودن سایت یا برگشتن به اپ، روز و ساعت دلخواه را تنظیم کن.</p><label class="field-label">ساعت یادآوری</label><input id="reminderTime" class="field" type="time" value="${escapeHTML(state.reminder?.time||'17:30')}"/><div class="field-label mt16">روزهای یادآوری</div><div class="reminder-days">${[6,0,1,2,3,4,5].map(d=>`<label><input type="checkbox" data-reminder-day="${d}" ${((state.reminder?.days)||[6,0,2,4]).includes(d)?'checked':''}/>${dayNames[d]}</label>`).join('')}</div><div class="chip-row mt16"><button class="btn primary" data-save-reminder="1">ذخیره زمان</button><button class="btn outline" data-enable-notification="1">فعال‌کردن اعلان‌ها</button><button class="btn ghost" data-test-notification="1">آزمایش اعلان</button></div><div class="chip-row mt16"><button class="btn primary" data-install="1">${ic('download','sm')} نصب MobinGYM</button><span class="chip" id="notificationStatus">${typeof Notification!=='undefined'?Notification.permission:'پشتیبانی نمی‌شود'}</span></div><div class="food-note">اعلان زمان‌بندی‌شده وقتی سایت کاملاً بسته است نیازمند سرویس Push و سرور ارسال‌کننده است؛ این نسخه محلی هنگام باز بودن/بازگشت اپ یادآوری می‌کند. نصب فقط روی HTTPS فعال می‌شود.</div></div><div class="card settings-card"><h3>${ic('sparkles','sm')} درباره MobinGYM</h3><p>نسخه اختصاصی تمرین و تغذیه برای کاهش چربی همراه با حفظ عضله. تقویم شمسی با تنظیم منطقه زمانی، نمایش سه‌بعدی تعاملی باشگاه، برنامه روزانه، گزارش تمرین و پشتیبان‌گیری.</p><div class="between"><span class="chip">VERSION 2.0 · PWA EDITION</span><span style="font-family:Arial;font-weight:900;color:#72caff">MobinGYM</span></div><div class="food-note">داده‌ها در این مرورگر باقی می‌مونن و در سرور عمومی یا GitHub منتشر نمی‌شن. انتشار سایت روی GitHub Pages به‌تنهایی به معنی اشتراک‌گذاری اطلاعات شخصی تو نیست.</div><div class="food-note"><a href="https://repdb.co" target="_blank" rel="noopener noreferrer">Exercise data by RepDB (repdb.co)</a> · موزیک‌های ذخیره‌شده در IndexedDB جزو بکاپ JSON نیستند.</div></div></div>`}
function render(){const host=document.getElementById('app');const view={home,workout:sessionPage,nutrition:nutritionPage,history:historyPage,music:musicPage,settings:settingsPage}[tab]();host.innerHTML=layout(view);if(tab==='home')setupScene();}
function openModal(markup){modalOpen=true;document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" id="backdrop"><div class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-close="1">${ic('x','sm')}</button>${markup}</div></div>`}
function closeModal(){modalOpen=false;document.getElementById('modalRoot').innerHTML=''}
function chooseModal(){openModal(`<span class="eyebrow">CHOOSE YOUR WORKOUT</span><h3>امروز کدوم جلسه رو بریم؟</h3><p>اگر برنامه هفته تغییر کرده، می‌تونی هر جلسه رو انتخاب کنی. بعد از پایان جلسه، پیشنهاد روز بعد هوشمندانه به‌روز می‌شه.</p><div class="selection-grid">${ORDER.map(id=>`<button class="select-card" data-choose="${id}"><b>${id}</b><strong>${plans[id].title}</strong><small>${plans[id].subtitle}</small></button>`).join('')}</div>`)}
function showPreview(id){const e=Object.values(plans).flatMap(p=>p.ex).find(x=>x[0]===id);if(!e)return;const text=encodeURIComponent(e[1]+' form exercise tutorial');openModal(`<div class="eyebrow">MOVEMENT LAB</div><h3>${escapeHTML(e[1])}</h3>${mediaHint(id)}<div class="movement-preview">${pic(e[5],true)}</div><div class="chip-row"><span class="chip">${num(e[2])} ست</span><span class="chip">${fi(e[3])} تکرار</span><span class="chip">${num(e[4])} ثانیه استراحت</span></div><div class="tip">${ic('info','sm')} ${escapeHTML(e[6])}</div><p class="sub">این یک راهنمای متحرک شماتیک است و جایگزین نمایش دقیق فرم انسانی نیست.</p><a class="btn primary btn-block" href="https://www.youtube.com/results?search_query=${text}" target="_blank" rel="noopener noreferrer">${ic('play','sm')} ویدئوهای واقعی این حرکت</a>`) }
function getOrCreate(plan){const day=today();let s=state.sessions[day];if(!s){s=newSession(plan);state.sessions[day]=s;}return s}
// Simple post-set rest timer. Only starts for a completed set; can be skipped.
let restInterval=null,restLeft=0,restTotal=0;
function paintTimer(){const node=document.getElementById('restTimer');if(!node)return;node.innerHTML=`<div class="timer-circle">${ic('clock','lg')}</div><div><strong>${Math.floor(restLeft/60).toString().padStart(2,'0')}:${(restLeft%60).toString().padStart(2,'0')}</strong><small>استراحت تا ست بعدی</small></div><div class="timer-actions"><button data-rest-more="1">+۳۰</button><button data-rest-skip="1">رد</button></div>`}
function stopRest(notifyEnd=false){clearInterval(restInterval);restInterval=null;document.getElementById('restTimer')?.remove();if(notifyEnd){toast('استراحت تمام شد؛ برای ست بعدی آماده‌ای!');try{navigator.vibrate?.([100,60,100])}catch(e){}}}
function startRest(seconds){stopRest();restLeft=seconds;restTotal=seconds;const node=document.createElement('div');node.className='rest-float';node.id='restTimer';document.body.append(node);paintTimer();restInterval=setInterval(()=>{restLeft=Math.max(0,restLeft-1);paintTimer();if(!restLeft)stopRest(true)},1000)}
document.addEventListener('click',e=>{if(e.target.closest('[data-rest-skip]')){stopRest();return}if(e.target.closest('[data-rest-more]')){restLeft+=30;paintTimer()}});

function checkSet(key){const [id,idx]=key.split(':');const plan=currentSession()?.plan||selectedPlan||recommend();const s=getOrCreate(plan);if(s.finishedAt){toast('برای اصلاح این جلسه ابتدا دکمه ویرایش رو بزن.');return}const prev=s.sets[key]||{};const ex=plans[s.plan].ex.find(x=>x[0]===id);const from=previousSet(id,Number(idx));s.sets[key]={...prev,weight:prev.weight??from?.weight,reps:prev.reps??from?.reps??suggestedReps(ex?.[3]||'10'),done:!prev.done,completedAt:!prev.done?Date.now():null};const p=progress(s);save();if(s.sets[key].done){const currentExercise=plans[s.plan].ex.find(x=>x[0]===id);if(currentExercise)startRest(currentExercise[4]);}else stopRest();const scroll=window.scrollY;render();window.scrollTo({top:scroll,behavior:'instant'});if(p.done===p.total){toast('همه ست‌ها تکمیل شدن! وقت ثبت نهایی جلسه‌ست. ✨');confetti(18)}else toast(`ست ${num(Number(idx)+1)} ${s.sets[key].done?'ثبت شد':'از حالت انجام‌شده خارج شد'}`)}
function confetti(n=30){for(let i=0;i<n;i++){const d=document.createElement('div');d.className='confetti';d.style.left=Math.random()*100+'vw';d.style.top='-25px';d.style.background=['#36bdff','#62ecc5','#a38afe','#ffca72'][i%4];d.style.animationDelay=Math.random()*.5+'s';d.style.transform=`rotate(${Math.random()*360}deg)`;document.body.append(d);setTimeout(()=>d.remove(),2200)}}
function finish(){let s=currentSession();if(!s){toast('اول ست‌های تمرین رو ثبت کن.');return}if(s.finishedAt){toast('این تمرین قبلاً ثبت شده.');return}const pp=progress(s);if(pp.done===0){toast('حداقل یک ست رو ثبت کن.');return}if(pp.done<pp.total&&!confirm(`فقط ${pp.done} ست از ${pp.total} ست ثبت شده. جلسه رو به‌صورت نیمه‌کامل تمام می‌کنی؟`))return;s.finishedAt=Date.now();stopRest();notify();confetti(70);toast('جلسه ثبت شد! آفرین، یک قدم قوی‌تر شدی.');}
function ensurePlan(plan){const log=currentSession();if(log&&log.plan!==plan){if(log.finishedAt){toast('جلسه امروز قبلاً ثبت شده؛ برای حفظ سابقه امکان جایگزینی اون نیست.');return false}const done=progress(log).done;if(done>0&&!confirm('امروز یک جلسه با ست‌های ثبت‌شده داری. برای تغییر جلسه، اطلاعات ست‌های امروز بازنشانی می‌شن. ادامه می‌دی؟'))return false;state.sessions[today()]=newSession(plan)}selectedPlan=plan;return true}
function startSession(){selectedPlan=currentSession()?.plan||recommend();goto('workout')}
function doExport(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString(),app:'MobinGYM'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`MobinGYM-backup-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('نسخه پشتیبان ساخته شد؛ در جای امن نگه دار.')}
async function doImport(file){try{const data=JSON.parse(await file.text());if(!data||data.version!==2||!data.sessions||!data.profile||!data.schedule||!Array.isArray(data.weights))throw Error('فایل پشتیبان معتبر نیست');if(!confirm('بازیابی، اطلاعات فعلی دستگاه رو با فایل انتخاب‌شده جایگزین می‌کنه. آیا مطمئنی؟'))return;state={...structuredClone(BASE),...data,profile:{...BASE.profile,...data.profile},nutrition:data.nutrition||{}};state.version=2;delete state.app;delete state.exportedAt;save();calendarOffset=0;render();toast('نسخه پشتیبان با موفقیت بازیابی شد.')}catch(e){toast('بازیابی ناموفق: '+e.message)}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-tab],[data-start],[data-open],[data-select-plan],[data-ex],[data-set-done],[data-quick-set],[data-preview],[data-finish],[data-reopen],[data-meal],[data-swap-meal],[data-portion],[data-water],[data-coffee],[data-remove-coffee],[data-remove-food],[data-cal-nav],[data-export],[data-import],[data-close],[data-choose],[data-fill-last],[data-save-reminder],[data-enable-notification],[data-test-notification],[data-install],.stepper button,[data-music-action],[data-track-id]');if(!el){if(e.target.id==='backdrop')closeModal();return}
if(el.dataset.tab){goto(el.dataset.tab);return}if(el.hasAttribute('data-start')){startSession();return}if(el.dataset.open==='choose'){chooseModal();return}if(el.dataset.selectPlan){if(ensurePlan(el.dataset.selectPlan))notify();return}if(el.dataset.ex){openEx=openEx===el.dataset.ex?null:el.dataset.ex;const y=window.scrollY;render();window.scrollTo({top:y,behavior:'instant'});return}if(el.dataset.quickSet){markNextSet(el.dataset.quickSet);return}if(el.dataset.setDone){checkSet(el.dataset.setDone);return}if(el.dataset.preview){showPreview(el.dataset.preview);return}if(el.hasAttribute('data-finish')){finish();return}if(el.hasAttribute('data-reopen')){state.sessions[today()].finishedAt=null;notify();toast('جلسه برای ویرایش باز شد.');return}if(el.dataset.meal){const d=nutritionDay();d.checked[el.dataset.meal]=!d.checked[el.dataset.meal];notify();if(d.checked[el.dataset.meal]){try{navigator.vibrate?.(20)}catch(e){}}return}if(el.dataset.swapMeal){const d=nutritionDay(),m=MEALS.find(x=>x.id===el.dataset.swapMeal);d.options[m.id]=((d.options[m.id]||0)+1)%m.choices.length;notify();return}if(el.dataset.portion){const [id,p]=el.dataset.portion.split(':');nutritionDay().portions[id]=Number(p);notify();return}if(el.dataset.water){const d=nutritionDay();d.water=Math.max(0,Math.min(32,d.water+Number(el.dataset.water)));notify();return}if(el.dataset.coffee){const [name,mg]=el.dataset.coffee.split(':');nutritionDay().caffeine.push({name,mg:Number(mg),at:Date.now()});notify();toast('قهوه ثبت شد ☕');return}if(el.dataset.removeCoffee!=null){nutritionDay().caffeine.splice(Number(el.dataset.removeCoffee),1);notify();return}if(el.dataset.removeFood!=null){nutritionDay().extras.splice(Number(el.dataset.removeFood),1);notify();return}if(el.dataset.calNav){calendarOffset=Math.max(-24,Math.min(24,calendarOffset+Number(el.dataset.calNav)));render();return}if(el.hasAttribute('data-export')){doExport();return}if(el.hasAttribute('data-import')){document.getElementById('importFile')?.click();return}if(el.hasAttribute('data-close')){closeModal();return}if(el.dataset.fillLast){applyPrevious(el.dataset.fillLast);return}if(el.closest('.stepper')){quickAdjust(el);return}if(el.dataset.choose){if(ensurePlan(el.dataset.choose)){closeModal();goto('workout')}return}if(el.dataset.musicAction){musicAction(el.dataset.musicAction);return}if(el.dataset.trackId){playTrack(Number(el.dataset.trackId));return}if(el.hasAttribute('data-save-reminder')){saveReminder();return}if(el.hasAttribute('data-enable-notification')){enableNotification();return}if(el.hasAttribute('data-test-notification')){sendReminder('آزمایش اعلان MobinGYM','اعلان‌های اپ فعال هستند.');return}if(el.hasAttribute('data-install')){installApp();return}});

document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.setField){const s=getOrCreate(currentSession()?.plan||selectedPlan);const key=`${el.dataset.exid}:${el.dataset.set}`;const val=el.value===''?undefined:Number(el.value);s.sets[key]={...(s.sets[key]||{}),[el.dataset.setField]:val};save();return}if(el.dataset.schedule){const id=el.dataset.schedule,d=Number(el.value),oldKey=Object.keys(state.schedule).find(k=>state.schedule[k]===id),existing=state.schedule[d];if(oldKey!==undefined)delete state.schedule[oldKey];if(existing&&existing!==id&&oldKey!==undefined)state.schedule[oldKey]=existing;state.schedule[d]=id;notify();toast('زمان‌بندی جدید ذخیره شد.');return}if(el.id==='importFile'&&el.files?.[0]){await doImport(el.files[0]);return}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.setField){const s=getOrCreate(currentSession()?.plan||selectedPlan);const key=`${el.dataset.exid}:${el.dataset.set}`;const val=el.value===''?undefined:Number(el.value);s.sets[key]={...(s.sets[key]||{}),[el.dataset.setField]:val};save()}});
document.addEventListener('submit',e=>{if(e.target.id==='extraFoodForm'){e.preventDefault();const fd=new FormData(e.target);const name=String(fd.get('name')||'').trim(),k=Number(fd.get('k')),p=Number(fd.get('p')||0);if(!name||!Number.isFinite(k)||k<0||k>3000||p<0||p>300)return;nutritionDay().extras.push({name,k,p,c:0,f:0,n:1});notify();toast('غذای دلخواه ثبت شد');return}if(e.target.id==='profileForm'){e.preventDefault();for(const field of ['weight','goal','calories','protein','carbs','fat','water'])state.profile[field]=Number(document.getElementById('p_'+field).value);state.profile.timezone=document.getElementById('p_timezone').value;notify();toast('هدف‌های شخصی ذخیره شدن.');return}if(e.target.id==='weightForm'){e.preventDefault();const weight=Number(document.getElementById('newWeight').value);if(weight<20||weight>400)return;const date=today(),waist=document.getElementById('newWaist').value,entry=state.weights.find(x=>x.date===date);if(entry){entry.weight=weight;if(waist!=='')entry.waist=Number(waist)}else state.weights.push({date,weight,...(waist!==''?{waist:Number(waist)}:{})});state.weights.sort((a,b)=>a.date.localeCompare(b.date));notify();toast('وزن امروز ثبت شد.');return}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalOpen)closeModal();if(e.key==='Enter'&&document.activeElement?.classList.contains('mini-lifter'))document.activeElement.click()});
document.addEventListener('click',e=>{const actor=e.target.closest('.mini-lifter');if(actor){actor.classList.remove('tumble');void actor.getBoundingClientRect();actor.classList.add('tumble');setTimeout(()=>actor.classList.remove('tumble'),2500);toast('تعادل از دست رفت! 😄')}});

let installPrompt=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;const installBtn=document.getElementById('installFloat');if(installBtn)installBtn.hidden=false});
window.addEventListener('appinstalled',()=>{installPrompt=null;document.getElementById('installFloat')?.setAttribute('hidden','');toast('MobinGYM به صفحه اصلی اضافه شد!')});
setTimeout(()=>{const btn=document.getElementById('installFloat');if(btn&&!window.matchMedia('(display-mode: standalone)').matches)btn.hidden=false},1500);
async function installApp(){if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('در Chrome از منوی سه‌نقطه گزینه Install app یا Add to Home screen را انتخاب کن. نصب به HTTPS نیاز دارد.')}
function saveReminder(){const time=document.getElementById('reminderTime')?.value||'17:30';const days=Array.from(document.querySelectorAll('[data-reminder-day]:checked')).map(x=>Number(x.dataset.reminderDay));state.reminder={time,days,enabled:true,last:''};save();toast('تنظیم یادآور ذخیره شد.');render()}
async function enableNotification(){if(!('Notification' in window)){toast('مرورگر از اعلان پشتیبانی نمی‌کند.');return}if(!isSecureContext){toast('اعلان‌ها فقط روی HTTPS یا localhost فعال‌اند.');return}const result=await Notification.requestPermission();if(result==='granted'){toast('اجازه اعلان فعال شد.');state.reminder=state.reminder||{time:'17:30',days:[6,0,2,4],enabled:true,last:''};save()}else toast('اجازه اعلان داده نشد.');render()}
async function sendReminder(title,body){if(!('Notification' in window)||Notification.permission!=='granted'){toast('ابتدا اجازه اعلان را فعال کن.');return}try{const reg=await navigator.serviceWorker?.ready;if(reg?.showNotification)await reg.showNotification(title,{body,icon:'./icon-192.png',badge:'./icon-192.png',tag:'mobingym-reminder',renotify:false});else new Notification(title,{body});}catch(e){new Notification(title,{body})}}
function checkReminders(){const r=state.reminder;if(!('Notification' in window)||!r?.enabled||Notification.permission!=='granted')return;const now=new Date(),parts=new Intl.DateTimeFormat('en-US',{timeZone:state.profile.timezone||'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(now),dict=Object.fromEntries(parts.filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));const localDate=`${dict.year}-${dict.month}-${dict.day}`,current=`${dict.hour}:${dict.minute}`;if(!(r.days||[]).includes(dayOf(localDate)))return;const key=localDate+'@'+r.time;if(current>=r.time&&r.last!==key){r.last=key;save();sendReminder('وقت باشگاهه! 💪','جلسه هوشمند امروزت در MobinGYM آماده است.')}}
async function bootPWA(){if('serviceWorker'in navigator&&location.protocol!=='file:'){try{await navigator.serviceWorker.register('./sw.js',{scope:'./'})}catch(e){console.warn('SW:',e)}}if('Notification' in window)checkReminders();setInterval(checkReminders,60_000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkReminders()});loadMusic()}

