 const signMat=new T.MeshBasicMaterial({map:new T.CanvasTexture(signCanvas),transparent:true,side:T.DoubleSide});const sign=box(5.05,1.34,.18,materials.dark,0,3.42,-4.01);const face=mesh(new T.PlaneGeometry(4.98,1.26),signMat);face.position.set(0,3.42,-3.90);
 // Dumbbell rack, weights, plates.
